mapper.select:
select psr.* from platform_statistics_report psr


        and `date` between #{reqVO.startDate} and #{reqVO.endDate}



        and psr.tenant_id = #{reqVO.tenantId}


order by psr.date desc

select psr.* from platform_statistics_week_report psr


        and `date` between #{reqVO.startDate} and #{reqVO.endDate}



        and psr.tenant_id = #{reqVO.tenantId}


order by psr.date desc

select psr.* from platform_statistics_month_report psr


        and `date` between #{reqVO.startDate} and #{reqVO.endDate}



        and psr.tenant_id = #{reqVO.tenantId}


order by psr.date desc
